/// Chain for a class id (1.12 `Classes` enum).
#[must_use]
pub fn chain_for(class_id: u8) -> &'static [ChainRow] {
    match class_id {
        1 => WARRIOR_CHAIN,
        2 => PALADIN_CHAIN,
        3 => HUNTER_CHAIN,
        4 => ROGUE_CHAIN,
        5 => PRIEST_CHAIN,
        7 => SHAMAN_CHAIN,
        8 => MAGE_CHAIN,
        9 => WARLOCK_CHAIN,
        11 => DRUID_CHAIN,
        _ => &[],
    }
}
